#include <stdint.h>
#define STM32G474xx
#include "stm32g4xx.h"
#include "adc.h"
#include "kobuki.h"
#include "uart.h"
#include "ultrasonic.h"
#include "SearchFSM.h"
#include "PathfindFSM.h"
#include "StorageFSM.h"
#include "DepositFSM.h"

/* Kobuki button values */
# define BUTTON_0_START 0x01U
# define BUTTON_1_STOP 0x02U
# define BUTTON_2_ROTATE 0x04U

// Logic
# define FALSE 0
# define TRUE 1
// States

// Define main FSM states
static enum {
    IDLE, 
    SEARCH,
    PATHFIND,
    STORAGE,
    DEPOSIT
} MainFSM_State;

int main(void) {
    // Initialise variables
    Kobuki_Typedef kobuki;
    US_Typedef object;
    Kobuki_LED_Enum led_1 , led_2;

    // Initialise peripherals
    UART_Init();
    ADC_Init();
    Ultrasonic_Init();
    MainFSM_State = IDLE;
    led_1 = OFF;
    led_2 = OFF;

    while (1){
        // Read peripheral states
        Kobuki_Read(&kobuki);
        Ultrasonic_Detect(&object);

        // Update LED's each loop
        Kobuki_Update_LEDs (led_1 , led_2 );

        // Emergency stop , applies to every state except IDLE
        if ((MainFSM_State != IDLE) && ((kobuki.wheeldrop != FALSE) || (kobuki.button == BUTTON_1_STOP))){
            MainFSM_State = IDLE;
            
            Kobuki_Drive(STOP);
        }

        // Main FSM
        switch(MainFSM_State){
            case IDLE:
                // Set LED's for IDLE state. Sit still waiting for the start button.
                led_1 = GREEN;
                led_2 = OFF;
                Kobuki_Drive(STOP);

                // Transition to SEARCH state. Initialise sub fsm
                if(kobuki.button == BUTTON_0_START){
                    SearchFSM_Reset();      
                    MainFSM_State = SEARCH;
                } 
                break;

            case SEARCH:
                // Set LED's for SEARCH state
                led_1 = YELLOW;
                led_2 = OFF;

                // Run SearchFSM each loop. Once it returns SEARCH_DONE, transition to ORIENT state
                if(SearchFSM_Run(&kobuki, &object) == SEARCH_DONE){
                    PathfindFSM_Reset();
                    MainFSM_State = PATHFIND;
                    Kobuki_Drive(STOP);
                }
                break;
            
            case PATHFIND:
                // Set LED's for PATHFIND state
                led_1 = GREEN;
                led_2 = GREEN;

                if (PathfindFSM_Run(&kobuki) == PATHFIND_DONE){
                    StorageFSM_Reset();
                    MainFSM_State = STORAGE;
                    Kobuki_Drive(STOP);
                }
                break;  

            case STORAGE:
                // Set LED's for STORAGE state
                led_1 = YELLOW;
                led_2 = YELLOW;

                if (StorageFSM_Run(&kobuki) == STORAGE_DONE){
                    DepositFSM_Reset();
                    MainFSM_State = DEPOSIT;
                    Kobuki_Drive(STOP);
                }
                break;  

            case DEPOSIT:
                // Set LED's for DEPOSIT state
                led_1 = RED;
                led_2 = RED;

                if (DepositFSM_Run(&kobuki, &object) == DEPOSIT_DONE){
                    MainFSM_State = IDLE;
                    Kobuki_Drive(STOP);
                }
                break;  
        }
    }
}
